const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairns = ee.Geometry.Point([145.78, -16.92]);
  const offshorePoint = cairns.transform('EPSG:4326', 100000); // Move 100km east
  const region = offshorePoint.buffer(10000); // 10km buffer for analysis

  // Time periods
  const baselineStart = '2003-01-01';
  const baselineEnd = '2014-12-31';
  const comparisonStart = '2022-03-01';
  const comparisonEnd = '2022-03-31';

  // 2. Data Acquisition - MODIS Aqua SST
  const sstCollection = ee.ImageCollection('MODIS/Aqua/L3SMI');

  // Baseline collection (2003-2014)
  const baselineCol = sstCollection
    .filterDate(baselineStart, baselineEnd)
    .select('sst');

  // March 2022 collection
  const march2022Col = sstCollection
    .filterDate(comparisonStart, comparisonEnd)
    .select('sst');

  // Check collection sizes
  const baselineSize = baselineCol.size().getInfo();
  const march2022Size = march2022Col.size().getInfo();

  console.log(`Baseline Images (2003-2014): ${baselineSize}`);
  console.log(`March 2022 Images: ${march2022Size}`);

  if (baselineSize === 0 || march2022Size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create composites and mask
  const baselineMean = baselineCol.mean().multiply(0.001); // Scale factor for SST
  const march2022Mean = march2022Col.mean().multiply(0.001);

  // Mask land pixels
  const landMask = sstCollection.first().select('land').eq(0);
  const baselineMasked = baselineMean.updateMask(landMask);
  const march2022Masked = march2022Mean.updateMask(landMask);

  // Check valid pixels
  const baselineCount = baselineMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const march2022Count = march2022Masked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`March 2022 valid pixels: ${march2022Count}`);

  if (baselineCount === 0 || march2022Count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean SST values
  const baselineSST = baselineMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const march2022SST = march2022Masked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  console.log(`Baseline SST (2003-2014): ${baselineSST?.toFixed(2)}°C`);
  console.log(`March 2022 SST: ${march2022SST?.toFixed(2)}°C`);

  // 5. Validation & Final Answer
  if (baselineSST === null || march2022SST === null || 
      isNaN(baselineSST) || isNaN(march2022SST)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = march2022SST - baselineSST;
  console.log(`Temperature difference: ${difference.toFixed(2)}°C`);

  if (Math.abs(difference) > 1.0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
